<template><div class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">Create ad</h1><form class="m-card space-y-3" @submit.prevent="submit"><input v-model="form.title" class="m-input" required placeholder="Campaign title"/><select v-model="form.listing_id" class="m-input"><option value="">No listing</option><option v-for="x in listings" :key="x.id" :value="x.id">{{ x.title }}</option></select><input v-model.number="budget" class="m-input" type="number" min="1" step="0.01" placeholder="Budget"/><input v-model.number="bid" class="m-input" type="number" min="0.01" step="0.01" placeholder="Bid per click"/><button class="m-btn-primary">Create draft</button></form></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const api=useCommerce();const {apiFetch}=useApi();const listings=ref<any[]>([]);const budget=ref(100);const bid=ref(1);const form=reactive({title:'',listing_id:'',placement:'MARKETPLACE',currency:'USD'});async function submit(){await apiFetch('/cebu-trade/ads/campaigns',{method:'POST',body:{...form,listing_id:form.listing_id||null,budget_minor:Math.round(budget.value*100),bid_per_click_minor:Math.round(bid.value*100)}});await navigateTo('/supplier/ads')}onMounted(async()=>listings.value=(await api.listSupplierListings('active')).items)</script>
